paramsDict = {} if value['showDisabled'] else {'enabled': True}
data = system.kanoa.tooling.getCounters(paramsDict)
if data is None or isinstance(data, basestring): return []
rows = system.kanoa.utilities.convertDatasetToJSON(data)
#Where each tool is: on a machine, or in a pocket of another tool
places = {}
for t in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.tooling.getTools(paramsDict) or []):
	if t['mountedOnAssetName']: places[t['toolingAssetId']] = t['mountedOnAssetName']
	elif t['mountedInToolingName']: places[t['toolingAssetId']] = '%s, pocket %s' % (t['mountedInToolingName'], t['parentPositionNumber'])
for row in rows:
	pcts = [row[k] for k in ('lifetimePct', 'pmPct', 'refurbPct', 'refurbCountPct', 'calibrationPct') if row.get(k) is not None]
	row['worstPct'] = max(pcts) if pcts else None
	where = places.get(row['toolingAssetId'])
	row['mountedOn'] = where or (row['hostAssetName'] if row['isMounted'] else '')
	row['lifeIn'] = {'cycles': 'Cycles', 'runMinutes': 'Run minutes', 'calendarDays': 'Calendar days'}.get(row['lifeUnit'], '')
return rows

